            L($"screens: {live} live tac pages (Cockpit.tacScreenRender = {tacR.name}; deck {string.Join(", ", deckScreenLog.Select(kv => kv.Key.Replace("cockpit_screen_deck_", "") + " " + kv.Value))}; WSO / EWO), {dark} other screens = Touchscreen_off");

