        // =================================================================== 1.9.3 tac-page layouts on the cockpit screens
        // The CI-22 page (tacScreen_cricket) in its 1024 x 512 render texture: map u 0.001-0.791 (full height, upright); three panels in the right
        // column, rotated (screen right -> +v, screen up -> -u): power (v 0.718-0.979), engine dials (0.390-0.697), attitude (0.025-0.341). Same
        // regions as TacScreenMesh (the B-25H / GA-25X layout proven in game). One screen = a backing quad (submesh 1, dark glass) + content quads
        // (submesh 0, tacScreenDisplay) 0.6 mm in front, scaled to fit with the page's own aspect (no stretch), centred.
        static readonly (float u0, float u1, float v0, float v1)[] TacPanelUV = { (0.802f, 0.983f, 0.718f, 0.979f), (0.801f, 0.985f, 0.390f, 0.697f), (0.789f, 0.983f, 0.025f, 0.341f) };
        static readonly (float u0, float u1, float v0, float v1) TacMapUV = (0.001f, 0.791f, 0f, 1f);
        static readonly List<string> ewScreenLog = new List<string>();
        static readonly Dictionary<string, string> stationScreenLog = new Dictionary<string, string>();
        static readonly Dictionary<string, string> deckScreenLog = new Dictionary<string, string>();   // 1.9.5 deck MFDs: name -> content
        static int ewScreensFound, ewScreensLive, ewScreensDark; static bool ewLayoutOk;
        class ScreenRect { public Vector3 o, ex, ey, n; public float W, H; public bool flip; public string role, content; }

        // elements of a content kind: (uv rect, rotated, on-screen aspect w / h)
        static List<((float u0, float u1, float v0, float v1) r, bool rot, float aspect)> TacElements(string content)
        {
            var l = new List<((float u0, float u1, float v0, float v1) r, bool rot, float aspect)>();
            float PA((float u0, float u1, float v0, float v1) q) => (q.v1 - q.v0) * 512f / ((q.u1 - q.u0) * 1024f);
            if (content == "map") l.Add((TacMapUV, false, (TacMapUV.u1 - TacMapUV.u0) * 1024f / ((TacMapUV.v1 - TacMapUV.v0) * 512f)));
            if (content == "panels12" || content == "panels") { l.Add((TacPanelUV[0], true, PA(TacPanelUV[0]))); l.Add((TacPanelUV[1], true, PA(TacPanelUV[1]))); }
            if (content == "panel3" || content == "panels") l.Add((TacPanelUV[2], true, PA(TacPanelUV[2])));
            return l;
        }

        // all screens into one two-submesh mesh; `ok` false when a content quad leaves its screen
        static Mesh ScreensMesh(string name, List<ScreenRect> screens, out bool ok)
        {
            ok = true;
            const float lift = 0.0006f, g = 0.004f;
            var v = new List<Vector3>(); var uv = new List<Vector2>(); var t0 = new List<int>(); var t1 = new List<int>();
            foreach (var s in screens)
            {
                Vector3 P(float x, float y, float z) => s.o + s.ex * x + s.ey * y + s.n * z;
                void Quad(List<int> tris, float x0, float y0, float x1, float y1, float z, Vector2 a, Vector2 b, Vector2 c, Vector2 d)
                {
                    int i = v.Count;
                    v.Add(P(x0, y0, z)); v.Add(P(x1, y0, z)); v.Add(P(x1, y1, z)); v.Add(P(x0, y1, z));
                    uv.Add(a); uv.Add(b); uv.Add(c); uv.Add(d);
                    if (s.flip) tris.AddRange(new[] { i, i + 2, i + 1, i, i + 3, i + 2 }); else tris.AddRange(new[] { i, i + 1, i + 2, i, i + 2, i + 3 });
                }
                Quad(t1, 0, 0, s.W, s.H, 0, Vector2.zero, Vector2.right, Vector2.one, Vector2.up);
                var els = TacElements(s.content);
                if (els.Count == 0) continue;
                float sumA = els.Sum(e => e.aspect);
                float h = Mathf.Min(s.H - 2 * g, (s.W - 2 * g - (els.Count - 1) * g) / sumA);
                float x = (s.W - (sumA * h + (els.Count - 1) * g)) / 2, y0 = (s.H - h) / 2;
                foreach (var e in els)
                {
                    float w = e.aspect * h; var r = e.r;
                    if (!e.rot) Quad(t0, x, y0, x + w, y0 + h, lift, new Vector2(r.u0, r.v0), new Vector2(r.u1, r.v0), new Vector2(r.u1, r.v1), new Vector2(r.u0, r.v1));
                    else Quad(t0, x, y0, x + w, y0 + h, lift, new Vector2(r.u1, r.v0), new Vector2(r.u1, r.v1), new Vector2(r.u0, r.v1), new Vector2(r.u0, r.v0));
                    if (x < -1e-5f || x + w > s.W + 1e-5f || y0 < -1e-5f || y0 + h > s.H + 1e-5f || h <= 0f) ok = false;
                    x += w + g;
                }
            }
            var m = new Mesh { name = name };
            m.SetVertices(v); m.SetUVs(0, uv); m.subMeshCount = 2; m.SetTriangles(t0, 0); m.SetTriangles(t1, 1);
            m.RecalculateNormals(); m.RecalculateTangents(); m.RecalculateBounds();
            generatedMeshes.Add(m);
            return m;
        }

        // one of our station screens (contract quad, UV 0..1: +u = screen right, +v = up, the TacScreenMesh frame)
        static Mesh StationScreenMesh(Mesh src, string name, string content)
        {
            var sv = src.vertices; var suv = src.uv;
            int Near(Vector2 q) { int b = 0; for (int i = 1; i < suv.Length; i++) if ((suv[i] - q).sqrMagnitude < (suv[b] - q).sqrMagnitude) b = i; return b; }
            Vector3 o = sv[Near(Vector2.zero)], ex = sv[Near(Vector2.right)] - o, ey = sv[Near(Vector2.up)] - o;
            var st = src.GetTriangles(0);
            var n = Vector3.Cross(sv[st[1]] - sv[st[0]], sv[st[2]] - sv[st[0]]).normalized;
            var s = new ScreenRect { o = o, ex = ex.normalized, ey = ey.normalized, W = ex.magnitude, H = ey.magnitude, n = n, content = content, role = name };
            s.flip = Vector3.Dot(Vector3.Cross(s.ex, s.ey), n) < 0;
            var m = ScreensMesh(name, new List<ScreenRect> { s }, out bool ok);
            if (!ok) throw new Exception("station screen layout outside its screen: " + name);
            return m;
        }

        // the stock EW-25 wide tac screen: its connected pieces are the screen rectangles (UVs affine on each); fit P = o + u A + v B per piece
        // (least squares), take the UV bounding box -> the rectangle, screen up = the in-plane axis with the larger height change, right = +x
        static Mesh EwScreenMesh(Mesh src, string name)
        {
            var sv = src.vertices; var suv = src.uv; var tri = src.GetTriangles(0);
            var par = Enumerable.Range(0, sv.Length).ToArray();
            int F(int i) { while (par[i] != i) { par[i] = par[par[i]]; i = par[i]; } return i; }
            for (int k = 0; k < tri.Length; k += 3) { par[F(tri[k])] = F(tri[k + 1]); par[F(tri[k + 1])] = F(tri[k + 2]); }
            var groups = Enumerable.Range(0, sv.Length).GroupBy(F).ToList();
            var screens = new List<ScreenRect>();
            ewScreenLog.Clear();
            foreach (var gp in groups)
            {
                var idx = gp.ToList();
                // normal equations for the unknowns (o, A, B), rows (1, u, v); Cramer per unknown and coordinate
                double s00 = 0, s01 = 0, s02 = 0, s11 = 0, s12 = 0, s22 = 0; var r0 = Vector3.zero; var r1 = Vector3.zero; var r2 = Vector3.zero;
                foreach (var i in idx) { double u = suv[i].x, w = suv[i].y; s00 += 1; s01 += u; s02 += w; s11 += u * u; s12 += u * w; s22 += w * w; r0 += sv[i]; r1 += sv[i] * (float)u; r2 += sv[i] * (float)w; }
                double[,] M = { { s00, s01, s02 }, { s01, s11, s12 }, { s02, s12, s22 } };
                double D3(double[,] q) => q[0, 0] * (q[1, 1] * q[2, 2] - q[1, 2] * q[2, 1]) - q[0, 1] * (q[1, 0] * q[2, 2] - q[1, 2] * q[2, 0]) + q[0, 2] * (q[1, 0] * q[2, 1] - q[1, 1] * q[2, 0]);
                double det = D3(M);
                if (Math.Abs(det) < 1e-12) throw new Exception("EW screen piece with degenerate UVs (" + idx.Count + " vertices)");
                Vector3 Solve(int col)
                {
                    var res = Vector3.zero;
                    for (int c = 0; c < 3; c++)
                    {
                        double[] b = { r0[c], r1[c], r2[c] };
                        var Mc = (double[,])M.Clone(); for (int rr = 0; rr < 3; rr++) Mc[rr, col] = b[rr];
                        res[c] = (float)(D3(Mc) / det);
                    }
                    return res;
                }
                Vector3 O = Solve(0), A = Solve(1), B = Solve(2);
                float umin = idx.Min(i => suv[i].x), umax = idx.Max(i => suv[i].x), vmin = idx.Min(i => suv[i].y), vmax = idx.Max(i => suv[i].y);
                Vector3 au = A * (umax - umin), bv = B * (vmax - vmin), c0 = O + A * umin + B * vmin, ctr = c0 + au / 2 + bv / 2;
                bool uUp = Mathf.Abs(au.y) > Mathf.Abs(bv.y);
                Vector3 up = uUp ? au : bv, rt = uUp ? bv : au;
                if (up.y < 0) up = -up;
                if (rt.x < 0) rt = -rt;
                int t = -1; for (int k = 0; k < tri.Length; k += 3) if (idx.Contains(tri[k])) { t = k; break; }
                var n = Vector3.Cross(sv[tri[t + 1]] - sv[tri[t]], sv[tri[t + 2]] - sv[tri[t]]).normalized;
                var s = new ScreenRect { ex = rt.normalized, ey = up.normalized, W = rt.magnitude, H = up.magnitude, n = n };
                s.o = ctr - rt / 2 - up / 2;
                s.flip = Vector3.Dot(Vector3.Cross(s.ex, s.ey), n) < 0;
                float ax = Mathf.Abs(ctr.x);
                if (ax < 0.06f) { s.role = "centre top"; s.content = "dark"; }
                else if (s.H > s.W) { s.role = "side portrait"; s.content = "dark"; }
                else if (ctr.y > 0.22f) { s.role = ax > 0.32f ? "outer" : "inner"; s.content = ax > 0.32f ? "map" : "panels12"; }
                else { s.role = ax < 0.30f ? "lower centre" : "lower outer"; s.content = ax < 0.30f ? "panel3" : "dark"; }
                if (ax >= 0.06f) s.role += ctr.x < 0 ? " L" : " R";
                screens.Add(s);
            }
            screens = screens.OrderByDescending(s => s.o.y).ThenBy(s => s.o.x).ToList();
            var m = ScreensMesh(name, screens, out ewLayoutOk);
            ewScreensFound = screens.Count; ewScreensLive = screens.Count(s => s.content != "dark"); ewScreensDark = screens.Count(s => s.content == "dark");
            foreach (var s in screens) ewScreenLog.Add($"{s.role} {s.W:F3} x {s.H:F3} m -> {s.content}");
            return m;
        }
        // Hatch per contract: hatch_* rests identity under hatch_*_hinge (local +X = hinge axis). Canopy.CanopyHinge on the
        // hatch (absolute localEulerAngles = right * hingeAngle * open). For the jettison push (Canopy.FixedUpdate adds
        // ejectionForce along ejectionTransform.up/forward) an 'eject' frame whose +Y points out of the fuselage is placed
        // above the hinge and used as Canopy.ejectionTransform (it gets the Rigidbody and carries hinge + hatch away).
        static Canopy MakeHatchFromContract(Transform hatch, Transform hinge, float hingeAngle, AeroPart part, Renderer[] glass)
        {
            var mf = hatch.GetComponent<MeshFilter>();
            var centre = mf != null && mf.sharedMesh != null ? hatch.TransformPoint(mf.sharedMesh.bounds.center) : hatch.position;
            var pc = part.GetComponent<MeshCollider>() != null ? part.transform.TransformPoint(part.GetComponent<MeshCollider>().sharedMesh.bounds.center) : part.transform.position;
            var outward = centre - pc; outward.z = 0f; if (outward.sqrMagnitude < 1e-4f) outward = Vector3.up; outward.Normalize();
            var ej = NewGO(hatch.name + "_eject", hinge.parent, hinge.position, Quaternion.LookRotation(Vector3.ProjectOnPlane(Vector3.forward, outward).normalized, outward));
            hinge.SetParent(ej.transform, true);
            var box = hatch.gameObject.AddComponent<BoxCollider>();
            if (mf != null && mf.sharedMesh != null) { box.center = mf.sharedMesh.bounds.center; box.size = Vector3.Max(mf.sharedMesh.bounds.size, Vector3.one * 0.04f); }
            box.enabled = false;
            var drv = DrivenFrame(hatch);
            var cn = CloneComp(TplComp<Canopy>("COIN:canopyFrame_F"), hatch.gameObject);
            cn.ejectionTransform = ej.transform; cn.attachedPart = part; cn.mass = 50f; cn.ejectionCollider = box;
            S(cn, "ejectionForce", new Vector3(0f, 4000f, 0f)); // 800 N for fireTime 0.2 s on 20 kg = ~8 m/s out of the fuselage
            S(cn, "forcePosition", Vector3.zero);
            var h = NewElem(cn, "canopyHinges"); S(h, "transform", drv); S(h, "hingeAngle", hingeAngle);
            SetSeq(cn, "canopyHinges", new[] { h });
            S(cn, "fireTime", 0.2f); S(cn, "openSpeed", 0.6f);
            S(cn, "glassRenderers", glass);
            L($"hatch {hatch.name}: part {part.name}, hinge {hinge.position.ToString("F3")} axis {hinge.right.ToString("F2")} angle {hingeAngle}, eject push along {outward.ToString("F2")}, glass {glass.Length}");
            return cn;
        }

        // Cockpit animation with stock drivers only:
        //  - columns / wheels / pedals: ControlSurface with attachedSurface = fus_cockpit and visibleMesh = the control
        //    (ControlSurfaceJob_Math: rotation = rest * AngleAxis(pitch*pR + roll*rR + yaw*yR, X); visual only - the aero
        //    effect of real surfaces comes from their liftNormal being the visibleMesh, Aircraft.controlSurfaces only runs
        //    split-drag aero when maxSplit > 0);
        //  - manifold pressure and rpm needles: Cockpit.Throttle (rotation, localEulerAngles.x = throttle * range);
        //  - airspeed needle: HighLiftDevice with deployedArea 0 (position = 1 - v / vRet, linear in airspeed; rate 1/s).
        //  Altimeter, VSI, fuel, attitude and compass cards have no stock driver and stay at rest.
        static void CockpitAnimation(global::Cockpit ck, AeroPart cp)
        {
            cockpitAnimLog.Clear();
            var tplCS = TplComp<ControlSurface>("CAS1:elevator_L");
            foreach (var o in JList("controls", "objects"))
            {
                if (RemovePedals && ((string)o["name"]).StartsWith("cockpit_rudder_pedals")) continue;      // removed (DropPedals)
                var t = TryFind((string)o["name"]); if (t == null) { L($"WARN control {(string)o["name"]} not in the model"); continue; }
                var field = (string)o["drive"]["field"]; float val = (float)o["drive"]["value"];
                if (field == "pitchRange") val = ColumnPitchSign * Mathf.Abs(val);
                float servo = o["drive"]["servoSpeed"] != null ? (float)o["drive"]["servoSpeed"] : 90f;
                var cs = t.gameObject.AddComponent<ControlSurface>();
                EditorUtility.CopySerialized(tplCS, cs); Remap(cs);
                S(cs, "pitchRange", 0f); S(cs, "rollRange", 0f); S(cs, "yawRange", 0f); S(cs, "brakeRange", 0f);
                S(cs, field, val);
                S(cs, "attachedSurface", cp); S(cs, "visibleMesh", t.gameObject); S(cs, "flap", false); S(cs, "servoSpeed", servo);
                S(cs, "splitDrag", 0f); S(cs, "maxSplit", 0f); S(cs, "yawSplitFactor", 0f); S(cs, "splitUpper", null); S(cs, "splitLower", null); S(cs, "splitSound", null);
                cockpitAnimLog.Add($"{t.name}: ControlSurface.{field} {val} (axis {t.right.ToString("F2")})");
            }
            var throttles = new List<object>();
            foreach (var g in JList("gauges", "movers").Concat(JList("levers", "movers")))   // needles + quadrant throttle levers
            {
                var t = TryFind((string)g["name"]); if (t == null) continue;
                var drv = g["stock_driver"] as Newtonsoft.Json.Linq.JObject;
                var name = (string)g["name"];
                if (drv != null && ((string)drv["component"] ?? "").Contains("throttles"))
                {
                    float range = (float)drv["range"];
                    var d = DrivenFrame(t);
                    // FD-32 lesson: the lever's grip must move FORWARD at full throttle; flip the sign if it does not
                    var grip = t.GetComponentsInChildren<MeshFilter>(true).FirstOrDefault();
                    if (grip != null)
                    {
                        var top = grip.transform.TransformPoint(grip.sharedMesh.bounds.center + Vector3.up * grip.sharedMesh.bounds.extents.y);
                        var r0 = d.localRotation; d.localEulerAngles = new Vector3(range, 0, 0);
                        var top1 = grip.transform.TransformPoint(grip.sharedMesh.bounds.center + Vector3.up * grip.sharedMesh.bounds.extents.y);
                        d.localRotation = r0;
                        if (top1.z < top.z) { range = -range; cockpitAnimLog.Add($"{name}: range sign flipped so the grip moves forward at full throttle"); }
                        throttleForward[name] = Mathf.Abs(top1.z - top.z);
                    }
                    var th = NewElem(ck, "throttles");
                    S(th, "rotation", true); S(th, "motion", false); S(th, "transform", d);
                    S(th, "range", range);
                    throttles.Add(th);
                    cockpitAnimLog.Add($"{name}: Cockpit.Throttle rotation range {range} (throttle proxy)");
                }
                else if (name == "gauge_airspeed_needle")
                {
                    // angle = mph * deg_per_unit; HighLiftDevice: pos = clamp01(1 - max(v - 0, 0) / vRet): pos 1 at 0 m/s, 0 at vRet
                    float dpu = (float)g["deg_per_unit"], v1 = (float)g["v1"];
                    float vRet = v1 * 0.44704f; // mph -> m/s
                    var d = DrivenFrame(t);
                    var h = cp.gameObject.AddComponent<HighLiftDevice>();
                    S(h, "aeroPart", cp); S(h, "swingWingController", null);
                    S(h, "speedDeployed", 0f); S(h, "speedRetracted", vRet); S(h, "alphaMin", 0f); S(h, "alphaFactor", 0f); S(h, "deployedArea", 0f);
                    var mp = NewElem(h, "movingParts");
                    S(mp, "move", false); S(mp, "rotate", true); S(mp, "transform", d);
                    S(mp, "positionRetracted", Vector3.zero); S(mp, "positionDeployed", Vector3.zero);
                    S(mp, "anglesRetracted", new Vector3(v1 * dpu, 0, 0)); S(mp, "anglesDeployed", Vector3.zero);
                    SetSeq(h, "movingParts", new[] { mp });
                    cockpitAnimLog.Add($"{name}: HighLiftDevice airspeed 0..{vRet:F1} m/s -> 0..{v1 * dpu:F0} deg");
                }
                else cockpitAnimLog.Add($"{name}: no stock driver, at rest");
            }
            SetSeq(ck, "throttles", throttles);
            foreach (var s in cockpitAnimLog) L("cockpit anim " + s);
        }

        // =================================================================== 1.1.0: crew, hatches, turrets, cockpit animation
        // A pivot whose local X is the given world axis (ControlSurface, Canopy hinges and Cockpit throttles all rotate about
        // local X). 'up' is a hint for the pivot's local Y.
        static Quaternion AxisX(Vector3 axisW, Vector3 upHint)
        {
            var x = axisW.normalized;
            var y = Vector3.ProjectOnPlane(upHint, x); if (y.sqrMagnitude < 1e-6f) y = Vector3.ProjectOnPlane(Vector3.up, x); if (y.sqrMagnitude < 1e-6f) y = Vector3.ProjectOnPlane(Vector3.forward, x);
            y.Normalize();
            return Quaternion.LookRotation(Vector3.Cross(x, y), y);
        }

        // Insert a pivot above 'moving' (same parent, at 'pivotPos', local X = axis) and re-parent 'moving' under it.
        static Transform Pivot(Transform moving, Vector3 pivotPos, Vector3 axisW, Vector3 upHint, string name = null)
        {
            var pv = NewGO(name ?? moving.name + "_pivot", moving.parent, pivotPos, AxisX(axisW, upHint), moving.gameObject.layer);
            moving.SetParent(pv.transform, true);
            return pv.transform;
        }

        // --- crew of five (stock multi-crew: Aircraft.pilots[], Pilot.ejectionSeat false = bail-out; Aircraft.EjectionSequence
        // jettisons every Canopy, then spawns one PilotDismounted per live crew member from the last to the first, 1 s apart,
        // placed 2 m beside its UnitPart (PilotDismounted.FindDismountSpot, alternating sides from Pilot.exitDirection).
        class CrewSpec { public string role, part, hatch; public Transform eye; public Pilot.ExitDirection exit; }
        static readonly List<Pilot> crew = new List<Pilot>();

        static Pilot MakeCrewMember(CrewSpec c, int index)
        {   // GA-25X 0.3.1 kitbash: the stock figure keeps its stock EjectionSeat child (mesh ejectionSeat, material Seats): the seat in the
            // aircraft IS the seat that fires (Pilot.ejectionSeat true; Aircraft.EjectionSequence jettisons the Canopy hatches first)
            var src = index == 0 ? TplFind("COIN:pilot") : TplFind("COIN:WSO");
            var fig = (GameObject)Object.Instantiate(src.gameObject);
            fig.SetActive(true); fig.name = index == 0 ? "pilot" : "crew_" + c.role;
            foreach (var t in fig.GetComponentsInChildren<Transform>(true).Where(t => t.name == "EjectionSeat").ToList())
            {
                if (!EjectionSeats190) { Object.DestroyImmediate(t.gameObject); continue; }
                var mf = t.GetComponent<MeshFilter>(); var mr = t.GetComponent<MeshRenderer>();
                if (mf != null) mf.sharedMesh = Asset<Mesh>("Mesh/ejectionSeat_PLACEHOLDER.asset");
                if (mr != null) mr.sharedMaterials = new[] { Asset<Material>("Material/Seats_PLACEHOLDER.mat") };
                var sc = t.GetComponent<MeshCollider>();
                if (sc != null) sc.sharedMesh = Asset<Mesh>("Mesh/ejectionSeat_PLACEHOLDER.asset");
            }
            var part = parts[c.part];
            fig.transform.SetParent(c.eye.parent, false);
            var cam = fig.GetComponentsInChildren<Transform>(true).First(t => t.name == "helmetCamPoint");
            fig.transform.rotation = Quaternion.LookRotation(Vector3.ProjectOnPlane(c.eye.forward, Vector3.up).sqrMagnitude > 1e-4f ? Vector3.ProjectOnPlane(c.eye.forward, Vector3.up) : Vector3.forward, Vector3.up);
            fig.transform.position += c.eye.position - cam.position;
            foreach (var comp in fig.GetComponentsInChildren<Component>(true)) if (comp != null) Remap(comp);
            var pc = fig.GetComponent<Pilot>();
            S(pc, "aircraft", aircraft); S(pc, "unitPart", part); S(pc, "ejectionSeat", EjectionSeats190); S(pc, "autoTrimmer", controlsFilter);
            S(pc, "pilotCollider", fig.GetComponent<CapsuleCollider>());
            pc.exitDirection = c.exit;
            L($"crew {index} {c.role}: part {c.part}, eye {c.eye.position.ToString("F3")}, figure eye {cam.position.ToString("F3")}, exit {c.exit}, hatch {c.hatch}, ejection seat {EjectionSeats190}");
            if (index == 0) helmetCam = cam;
            return pc;
        }

        // ------------------------------------------------------------------ defensive stations
        static readonly string[] StationOrder = { "Chin", "Tail", "Dorsal", "Ventral" };
        static readonly Dictionary<string, string> StationLabel = new Dictionary<string, string> { { "Chin", "Chin 20mm" }, { "Tail", "Tail 20mm" }, { "Dorsal", "Dorsal Laser" }, { "Ventral", "Ventral Laser" } };
        static readonly Dictionary<string, WeaponInfo> stationInfos = new Dictionary<string, WeaponInfo>();
        class MsbTurret { public Turret turret; public Gun gun; public AeroPart part; public Transform mount; public string station; public bool laser; public GameObject laserGO; public Laser laserComp; }
        static readonly List<MsbTurret> turrets = new List<MsbTurret>();
        static WeaponInfo turretInfo; static WeaponMount ammoTurrets;
        static int exclusionConeCount;
        static AeroPart OwningPart(Transform t) { for (var x = t; x != null; x = x.parent) { var ap = x.GetComponent<AeroPart>(); if (ap != null) return ap; } return null; }

        // 20 mm: own WeaponInfo per station (stations are keyed by WeaponInfo, WeaponManager.cs 403-438: one per station so the chin and the
        // tail fire independently, the B-17G lesson); values in the stock 20 mm class (msb_head.cs Gun20*). Gun component = the stock
        // turret_20mm_rotary Gun (sounds, tracer, heat), two muzzles on our twin barrel tips, magazineCapacity = cycles (one cycle = both).
        // Lasers: the GA-25X pattern - the Laser lives in a mount prefab spawned on the aperture hardpoint (Hardpoint.SpawnMount casts every
        // BuiltInWeapon to Gun), the station starts with a proxy base Weapon carrying the laser info; HLT (LaserTrailer1) turret values, its
        // own TargetDetector (15 km), onlyDefensive (missiles aimed at us only).
        static void BuildTurrets()
        {
            turrets.Clear(); stationInfos.Clear(); exclusionConeCount = 0;
            var tGunPrefab = tpl["turret_20mm_rotary"];
            var tplGun = tGunPrefab.GetComponentInChildren<Gun>(true);
            var tplTurret20 = tGunPrefab.GetComponentInChildren<Turret>(true);
            var tLaser = tpl["Laser_EW1"].GetComponent<Laser>();
            var tTurL = tpl["LaserTrailer1"].GetComponentInChildren<Turret>(true);
            foreach (var tj in JList("turrets"))
            {
                var mount = TryFind((string)tj["mount"]["name"]); var az = TryFind((string)tj["az"]["name"]); var el = TryFind((string)tj["el"]["name"]);
                if (mount == null || az == null || el == null) { L($"WARN turret {(string)tj["mount"]["name"]}: objects missing, skipped"); continue; }
                var station = (string)tj["station"]; bool laser = (string)tj["weapon"] == "laser";
                if (laser && !LaserTurrets190) { L($"turret {mount.name}: laser off (LaserTurrets190)"); continue; }
                var part = OwningPart(mount);
                var tl = tj["Turret"];
                float trav = (float)tl["traverseRange"], emin = (float)tl["minElevation"], emax = (float)tl["maxElevation"];
                var rec = new MsbTurret { part = part, mount = mount, station = station, laser = laser };
                Turret tr;
                if (!laser)
                {
                    var info = Object.Instantiate(Asset<WeaponInfo>("MonoBehaviour/Gun20mm_Rotary_Turret_PLACEHOLDER.asset")); info.name = "MSB17_" + station.ToLowerInvariant() + "_20mm_info";
                    if (Gun20Custom190)
                    {
                        info.weaponName = $"DTC-20 Twin 20mm ({station})"; info.shortName = $"{station.ToUpperInvariant()} 20MM";
                        info.description = "DTC-20 automated twin 20 mm defence cannon: radar / EO-cued remote turret, two barrels on one cradle, 600 rounds per barrel. Engages aircraft (and missiles at short range) in its own sector.";
                        info.muzzleVelocity = Gun20Velocity; info.pierceDamage = Gun20Pierce; info.blastDamage = Gun20Blast; info.dragCoef = Gun20Drag;
                        info.massPerRound = Gun20MassPerRound; info.targetRequirements.maxRange = Gun20Range;
                    }
                    info.boresight = false;
                    info.effectiveness.antiSurface = 0f; info.effectiveness.antiRadar = 0f;      // B-17G 1.6.1 lesson: air targets only (no ground fire, no ground-target pull)
                    info.effectiveness.antiAir = 0.25f; info.effectiveness.antiMissile = TurretAntiMissile ? 0.1f : 0f;
                    AssetDatabase.CreateAsset(info, Folder + "/" + info.name + ".asset");
                    stationInfos[station] = info;
                    var muzzles = ((Newtonsoft.Json.Linq.JArray)tj["guns"]).Select(g => TryFind((string)g["muzzle"]["name"])).Where(m => m != null).ToList();
                    foreach (var a in tplGun.GetComponents<AudioSource>()) CloneComp(a, el.gameObject).loop = false;
                    var gun = CloneComp(tplGun, el.gameObject);
                    gun.attachedUnit = aircraft; gun.info = info;
                    S(gun, "muzzles", muzzles.ToArray());
                    S(gun, "magazineCapacity", Gun20Cycles); S(gun, "magazines", 0); S(gun, "startLoaded", true);
                    S(gun, "fireRate", Gun20Custom190 ? Gun20CyclesPerMin : (float)G(tplGun, "fireRate"));
                    S(gun, "recoilTransform", null); S(gun, "spinTransform", null); S(gun, "ejectionTransform", null); S(gun, "ejectionPrefab", null);
                    var ps = new List<ParticleSystem>(); foreach (var mz in muzzles) ps.AddRange(CopyMuzzleParticles(tplGun, mz));
                    S(gun, "muzzleParticles", ps.ToArray());
                    tr = CloneComp(tplTurret20 != null ? tplTurret20 : tTurL, az.gameObject);
                    S(tr, "attachedUnit", aircraft);
                    var fMode = Fld(typeof(Turret), "targetAcquisitionMode"); fMode.SetValue(tr, Enum.ToObject(fMode.FieldType, 0));
                    S(tr, "fireControl", null); S(tr, "firesWithoutAiming", false);
                    SetSeq(tr, "targetDetectors", new TargetDetector[0]);
                    var ws = (WeaponStation)System.Runtime.Serialization.FormatterServices.GetUninitializedObject(typeof(WeaponStation));
                    ws.Weapons = new List<Weapon> { gun }; ws.Turrets = new List<Turret> { tr };
                    SetSeq(tr, "weaponStations", new[] { ws });
                    S(tr, "aimSafetyWeapon", gun);
                    rec.gun = gun;
                    L($"turret {mount.name} ({station}): DTC-20 v0 {info.muzzleVelocity} pierce {info.pierceDamage} {G(gun, "fireRate")} cycles/min x {muzzles.Count} barrels, {Gun20Cycles} cycles = {Gun20Cycles * muzzles.Count} rds");
                }
                else
                {
                    var info = Object.Instantiate(tLaser.info); info.name = "MSB17_" + station.ToLowerInvariant() + "_laser_info";
                    info.weaponName = $"120kW Laser ({station})"; info.shortName = $"{station.ToUpperInvariant()} LASER";
                    AssetDatabase.CreateAsset(info, Folder + "/" + info.name + ".asset");
                    stationInfos[station] = info;
                    var ap = TryFind((string)tj["aperture"]["name"]);
                    var lgo = new GameObject("MSB17_" + station.ToLowerInvariant() + "_laser_mount") { layer = 14 };
                    var lroot = lgo.transform;
                    var lz = CloneComp(tLaser, lgo);
                    lz.attachedUnit = null; lz.info = info;
                    if (LaserBeam197) S(lz, "maxAngle", LaserBeamAngle197);   // 1.9.7: beam = bore line (stock 30)
                    var tBeam = TplFind("Laser_EW1:beam");
                    var beam = NewGO("laser_beam", lroot, lroot.position, lroot.rotation);
                    beam.transform.localScale = tBeam.localScale;
                    beam.AddComponent<MeshFilter>().sharedMesh = tBeam.GetComponent<MeshFilter>().sharedMesh;
                    var br = beam.AddComponent<MeshRenderer>(); br.sharedMaterials = tBeam.GetComponent<MeshRenderer>().sharedMaterials; br.enabled = false;
                    br.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                    S(lz, "beamRenderer", br); S(lz, "directionTransform", lroot);
                    var aimPS = TplFind("Laser_EW1:aimTransform").GetComponent<ParticleSystem>();
                    var lmps = aimPS != null ? new[] { CopyParticle(aimPS, lroot, lroot.position, "laser_muzzle") } : new ParticleSystem[0];
                    S(lz, "muzzleParticles", lmps);
                    foreach (var p in lmps) ourParticles.Remove(p);
                    if (lmps.Length > 0) S(lgo.AddComponent<SetGlobalParticles>(), "systems", lmps.ToList());
                    S(lz, "vehicularPowerSupply", false);
                    tr = CloneComp(tTurL, az.gameObject);
                    S(tr, "attachedUnit", aircraft);
                    var fMode = Fld(typeof(Turret), "targetAcquisitionMode"); fMode.SetValue(tr, Enum.ToObject(fMode.FieldType, 1));
                    var det = CloneComp(tTurL.GetComponent<TargetDetector>(), az.gameObject);
                    S(det, "attachedUnit", aircraft); S(det, "scanner", el); S(det, "part", part); S(det, "visualRange", 15000f);
                    SetSeq(tr, "targetDetectors", new[] { det });
                    S(tr, "fireControl", null); S(tr, "firesWithoutAiming", false);
                    var proxy = el.gameObject.AddComponent<Weapon>(); proxy.attachedUnit = aircraft; proxy.info = info; proxy.Rearmable = false;
                    var ws = (WeaponStation)System.Runtime.Serialization.FormatterServices.GetUninitializedObject(typeof(WeaponStation));
                    ws.Weapons = new List<Weapon> { proxy }; ws.Turrets = new List<Turret> { tr }; ws.WeaponInfo = info;
                    SetSeq(tr, "weaponStations", new[] { ws });
                    S(tr, "aimSafetyWeapon", null);
                    S(tr, "onlyDefensive", true);
                    rec.laserGO = lgo; rec.laserComp = lz;
                    L($"turret {mount.name} ({station}): 120 kW laser (power {G(lz, "power")} kW, maxAngle {G(lz, "maxAngle")}), aperture {(ap != null ? ap.position.ToString("F3") : "MISSING")}, own detector 15 km, onlyDefensive");
                }
                // 1.9.2: Turret.AimTurret elevates only while |traverse error| < 45 deg (Turret.cs 746): at 60 deg/s the dorsal head never left 0 before the missile arrived
                S(tr, "traverseRate", laser && LaserSlew192 ? Mathf.Max((float)tl["traverseRate"], LaserTraverseRate) : (float)tl["traverseRate"]); S(tr, "traverseRange", trav >= 180f ? 999999f : trav);
                S(tr, "elevationRate", (float)tl["elevationRate"]); S(tr, "minElevation", emin); S(tr, "maxElevation", emax);
                S(tr, "elevationTransform", el);
                // inclusion cone: full-traverse turrets about the mount's up (dorsal) / down (ventral) as the GA-25X laser; sector turrets as the B-17G
                Vector3 fwd = mount.forward; float cone;
                if (trav >= 180f) { bool ventral = emax <= 0f; fwd = ventral ? -mount.up : mount.up; cone = ventral ? 90f + emax + 1f : 90f - emin + 1f; }
                else cone = Mathf.Rad2Deg * Mathf.Acos(Mathf.Cos(trav * Mathf.Deg2Rad) * Mathf.Cos(Mathf.Max(Mathf.Abs(emin), Mathf.Abs(emax)) * Mathf.Deg2Rad)) + 1f;
                var cg = NewGO(mount.name + "_cone", mount.parent, mount.position, Quaternion.LookRotation(fwd, Mathf.Abs(Vector3.Dot(fwd, Vector3.up)) > 0.99f ? Vector3.forward : Vector3.up));
                var fc = New(typeof(FiringCone)); S(fc, "transform", cg.transform); S(fc, "coneAngle", cone); S(fc, "exclusion", false);
                SetSeq(tr, "firingCones", new List<object> { fc });
                S(tr, "criticalParts", new UnitPart[] { part });
                S(tr, "manual", false); S(tr, "stowed", false);
                rec.turret = tr;
                turrets.Add(rec);
                L($"turret {mount.name}: part {part.name}, traverse {trav}, el {emin}..{emax}, inclusion cone {cone:F0} deg");
            }
        }

        // ------------------------------------------------------------------ root systems
        static void RootSystems(List<LandingGear> gears)
        {
            var coin = tpl["COIN"]; var ew1 = tpl["EW1"]; var ab4 = tpl["FastBomber1"];
            // optical search sensor: the AB-4's TargetDetector (heavy-bomber EOTS values) when the template has one, else the CI-22's
            var dsrc = ab4.GetComponent<TargetDetector>() ?? coin.GetComponent<TargetDetector>();
            if (ab4.GetComponent<TargetDetector>() == null) dsrc = coin.GetComponent<TargetDetector>();
            var detector = CloneComp(dsrc, root);
            S(detector, "attachedUnit", aircraft); S(detector, "scanner", parts["fus_cockpit"].transform);
            aircraft.EOTS = detector;
            // air-search radar, 60 km (user decision 2026-11-10): the EW-25's Radar values with maxRange 60 km, antenna in the nose
            if (Radar190)
            {
                var ant = NewGO("radar_antenna", parts["fus_nose"].transform, root.transform.TransformPoint(new Vector3(0f, 0.55f, 6.9f)), Quaternion.identity);
                var radar = CloneComp(ew1.GetComponent<Radar>(), root);
                S(radar, "attachedUnit", aircraft); S(radar, "scanner", ant.transform);
                var so = new SerializedObject(radar); var mr = so.FindProperty("RadarParameters.maxRange"); if (mr != null) { mr.floatValue = RadarRange; so.ApplyModifiedPropertiesWithoutUndo(); }
                try { S(aircraft, "radar", radar); } catch (Exception e) { L("note: no Unit.radar field to set (" + e.Message + ")"); }
                L($"radar: EW-25 values, maxRange {RadarRange / 1000f:F0} km, antenna {ant.transform.position.ToString("F2")}");
            }
            // power: capacitor charged by all four engines (PowerSupply: charge += chargePerRPM x engine rpm per second, PowerSupply.cs 86-91)
            var cap = CloneComp(TplAudio("COIN:COIN", "capacitor"), root);
            var power = CloneComp(ew1.GetComponent<PowerSupply>(), root);
            S(power, "powerSources", EngineNums.Select(n => parts["engine_" + n].gameObject).ToArray());
            S(power, "maxCharge", PowerMaxCharge); S(power, "chargePerRPM", PowerChargePerRPM); S(power, "maxPower", 2f * LaserPowerKW + JammerPowerKW);
            S(power, "source", cap); S(power, "aircraft", aircraft);
            S(aircraft, "powerSupply", power);
            if (RadarJammer190)
            {
                var jam = CloneComp(ew1.GetComponent<RadarJammer>(), root);   // EW-25: jammingIntensity 8, capacitance 100
                S(jam, "aircraft", aircraft); S(jam, "powerUsage", JammerPowerKW);
            }
            CloneComp(coin.GetComponent<NuclearOption.NetworkTransforms.AircraftNetworkTransform>(), root);

            // fuel 10,000 kg (B-17G wreck-fire method: one FuelTank per tank-carrying part, on the part's own GameObject, AB-4 heavy-bomber
            // settings, linked); SelfSealing190: half the leak per hit point and leak rate, 1.5 x the ignition thresholds (the sheet's
            // compartmentalised self-sealing tanks; the fields exist in FuelTank.cs 8-40)
            var tplWingTank = TplComp<FuelTank>("FastBomber1:wingroot_L");
            var tplBodyTank = TplComp<FuelTank>("FastBomber1:fuselage_R");
            tplWingLeakPerHP190 = (float)G(tplWingTank, "leakPerHP");     // for the check (the templates are unloaded before RunCheck)
            var tankKg = new List<(string part, float kg, FuelTank tpl)>();
            foreach (var sd in new[] { "L", "R" })
            {
                tankKg.Add(("wing_inner_" + sd, 2000f, tplWingTank));
                tankKg.Add(("wing_mid_" + sd, 1400f, tplWingTank));
                tankKg.Add(("wing_outer_" + sd, 700f, tplWingTank));
            }
            foreach (var n in EngineNums) tankKg.Add(("nacelle_" + n, 50f, tplWingTank));
            tankKg.Add(("MSB17", 1200f, tplBodyTank));
